const home = { name: 'Berlin', lat: 52.52, lon: 13.41 };   // ← your town
const maxKm = 1500;                                       // ← how close is "close"
const iss = $input.first().json;
const R = 6371, rad = d => d * Math.PI / 180;             // great-circle distance (haversine)
const a = Math.sin(rad(iss.latitude - home.lat) / 2) ** 2
        + Math.cos(rad(home.lat)) * Math.cos(rad(iss.latitude)) * Math.sin(rad(iss.longitude - home.lon) / 2) ** 2;
const km = Math.round(2 * R * Math.asin(Math.sqrt(a)));
const mem = $getWorkflowStaticData('global');
if (km > maxKm || (mem.last && Date.now() - mem.last < 80 * 60000)) return [];  // once per pass
mem.last = Date.now();
return [{ json: {
  title: `ISS ${km} km from ${home.name}`,
  message: `It flies at ${Math.round(iss.velocity)} km/h, ${Math.round(iss.altitude)} km high, `
         + (iss.visibility === 'daylight' ? 'in sunlight right now.' : "in the earth's shadow right now."),
  click: `https://www.openstreetmap.org/?mlat=${iss.latitude}&mlon=${iss.longitude}#map=4/${iss.latitude}/${iss.longitude}`,
  tags: ['satellite'] } }];
